import { usePrefix } from '../../internal/usePrefix';
import { useMergedRefs } from '../../internal/useMergedRefs';

/** @type any */
const InlineCheckbox = React.forwardRef(function InlineCheckbox(
  props,
  forwardRef
) {
  const {
    ariaLabel,
    checked = false,
    disabled,
    id,
    indeterminate,
    name,
    onChange = () => {},
    onClick,
    onKeyDown,
    title,
  } = props;
  const prefix = usePrefix();
  const inputRef = useRef(null);
  const ref = useMergedRefs([inputRef, forwardRef]);
  const inputProps = {
    checked,
    className: `${prefix}--checkbox`,
    disabled,
    id,
    name,
    onClick,
    onChange: (evt) => {
      onChange(evt.target.checked, id, evt);
    },
    onKeyDown,
    ref,
    type: 'checkbox',
  };

  if (indeterminate) {
    inputProps.checked = false;
  }

  useEffect(() => {
    inputRef.current.indeterminate = indeterminate;
  }, [indeterminate]);

  return (
    <div className={`${prefix}--checkbox--inline`}>
      <input {...inputProps} />
      {
        /* eslint-disable jsx-a11y/label-has-for,jsx-a11y/label-has-associated-control,jsx-a11y/click-events-have-key-events,jsx-a11y/no-noninteractive-element-interactions */
        <label
          htmlFor={id}
          className={`${prefix}--checkbox-label`}
          aria-label={ariaLabel}
          title={title}
          onClick={(evt) => {
            evt.stopPropagation();
          }}
        />
      }
    </div>
  );
});

